  'jazzy_hip_hop': {
    parent: 'mcRhythm.usHipHop',
    axes: { harm: 2, pitch: 1, ornament: 1, meter: 1, density: 1, transmission: 1, improv: 1, soundTech: 1, intensity: 0, voice: 2, timbre: 1, percussion: 2, cyclicity: 0 },
    description: '2010s lo-fi hip-hop subgenre developed through YouTube streaming-channel infrastructure (especially the canonical ChilledCow / Lofi Girl 24/7 stream launched 2017, and parallel College Music, Chillhop Music streams). Characterized by jazz-piano-and-trumpet sampling, mellow-and-relaxed drum-machine production, lo-fi-cassette-tape distortion aesthetic, and explicit "study music" and "ambient productivity" functional context. Nujabes (foundational, 1974-2010), J Dilla (foundational), Idealism, Jinsang, and the broader Lofi Girl roster anchor the canonical lo-fi hip-hop roster.',
    exemplars: ['Nujabes (foundational)', 'J Dilla (foundational)', 'Idealism', 'Jinsang', 'Engelwood', 'Lofi Girl'],
    status: 'documented',
    crossRefs: ['experimentalElec.ambient'],
  },
